namespace ghidra.app.util.viewer.format.actions;

using docking;
using docking.action;
using docking.action;
using ghidra.app.util;
using ghidra.app.util.viewer.field;
using ghidra.app.util.viewer.format;
using ghidra.util;

/**
 * The action for adding a Field to the current format.
 */
public class AddFieldAction : DockingAction {
	private FieldHeader panel;
	private FieldFormatModel formatModel;
	private FieldFactory myFieldFactory;

	public AddFieldAction(string owner, FieldFactory fieldFactory, FieldHeader panel,
			FieldFormatModel formatModel) : base(fieldFactory.getFieldName(), owner, false)
    {
		this.myFieldFactory = fieldFactory;
		this.formatModel = formatModel;
		this.panel = panel;

		setPopupMenuData(
			new MenuData(new string[] { "Add Field", fieldFactory.getFieldName() }, "header b"));
		setEnabled(true);
		setHelpLocation(new HelpLocation(HelpTopics.CODE_BROWSER, "Add Field"));
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context.getContextObject() is FieldHeaderLocation)) {
			return false;
		}

		FieldFactory[] unusedFactories = formatModel.getUnusedFactories();
		foreach (FieldFactory unusedFieldFactory in unusedFactories) {
			if (unusedFieldFactory == myFieldFactory) {
				return true;
			}
		}
		return false;
	}

	/* @Override */
	public bool isValidContext(ActionContext context) {
		if (!(context.getContextObject() is FieldHeaderLocation)) {
			return false;
		}

		FieldHeaderLocation loc = (FieldHeaderLocation) context.getContextObject();
		FieldFormatModel modelAtLocation = loc.getModel();
		return (modelAtLocation == formatModel);
	}

	/**
	 * Method called when the action is invoked.
	 */
	/* @Override */
	public void actionPerformed(ActionContext context) {
		FieldHeaderLocation loc = (FieldHeaderLocation) context.getContextObject();
		panel.setTabLock(true);
		formatModel.addFactory(myFieldFactory, loc.getRow(), loc.getColumn());
	}

	/* @Override */
	public string toString() {
		//@formatter:off
		return "{\n" +
			"\tfield: " + myFieldFactory.getFieldName() + "\n" +
			"\tmodel: " + formatModel.getName() + "\n" +
			"\towner: " + getOwner() + "\n" +
		"}";
		//@formatter:on
	}
}
